<script setup lang="ts">
import FieldError from '../FleetAndDocuments/components/FieldError.vue';
import {onBeforeUnmount,ref,watch,useId} from 'vue';
import {request,paginated,all} from '../Administration/api';
import {money,date} from '../BillingAndPayments/contracts';
import {localInstant,instant} from '../Workshop/presentation';
function costaRicaInput(value?:string):string{if(!value)return localInstant();const parts=new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Costa_Rica',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value));return parts.replace(' ','T');}
const costaRicaDate=instant;
import type {Expense} from './contracts';import {labels} from './contracts';
const props=defineProps<{admin:boolean;locked:boolean;epoch:number;errors:Record<string,string[]>}>();const emit=defineEmits<{command:[title:string,path:string,body:Record<string,unknown>,file?:File|null];error:[error:unknown]}>();
const rows=ref<Expense[]>([]),selected=ref<Expense|null>(null),trips=ref<{id:string;execution_status:string}[]>([]),loading=ref(false),page=ref(1),last=ref(1),search=ref(''),status=ref(''),currencyFilter=ref(''),from=ref(''),to=ref(''),tripFilter=ref('');let generation=0;let alive=true;
const concept=ref(''),category=ref(''),amount=ref(''),currency=ref<'CRC'|'USD'>('CRC'),occurredAt=ref(costaRicaInput()),description=ref(''),tripId=ref(''),editing=ref(false),reason=ref(''),decision=ref<'approved'|'rejected'>('approved'),decisionReason=ref(''),file=ref<File|null>(null);
async function load(number=1):Promise<void>{const current=++generation;loading.value=true;try{const q=new URLSearchParams({page:String(number),per_page:'15'});for(const[k,v]of Object.entries({search:search.value,status:status.value,currency:currencyFilter.value,from:from.value,to:to.value,trip_id:tripFilter.value}))if(v)q.set(k,v);const data=await paginated<Expense>(`/expenses?${q}`);if(current!==generation)return;rows.value=data.data;page.value=data.meta.current_page;last.value=data.meta.last_page;if(selected.value){const detail=await request<Expense>(`/expenses/${selected.value.id}`);if(current===generation)selected.value=detail;}}catch(e){if(current===generation)emit('error',e);}finally{if(current===generation)loading.value=false;}}
async function lookup():Promise<void>{try{const data=await all<{id:string;execution_status:string}>('/transport/trips');if(alive)trips.value=data;}catch(e){if(alive)emit('error',e);}}
async function inspect(row:Expense):Promise<void>{if(props.locked)return;const current=++generation;loading.value=true;try{const data=await request<Expense>(`/expenses/${row.id}`);if(current===generation){selected.value=data;file.value=null;decisionReason.value='';}}catch(e){if(current===generation)emit('error',e);}finally{if(current===generation)loading.value=false;}}
function correct():void{if(!selected.value)return;const row=selected.value;editing.value=true;concept.value=row.concept;category.value=row.category;amount.value=row.amount;currency.value=row.currency;occurredAt.value=costaRicaInput(row.occurred_at);description.value=row.description??'';tripId.value=row.trip_id??'';reason.value='';}
function reset():void{editing.value=false;concept.value='';category.value='';amount.value='';description.value='';reason.value='';tripId.value='';occurredAt.value=costaRicaInput();}
function submit():void{const body:Record<string,unknown>={concept:concept.value,category:category.value,amount:amount.value,currency:currency.value,occurred_at:costaRicaDate(occurredAt.value),description:description.value||null};if(editing.value&&selected.value){body.reason=reason.value;body.supersedes_id=selected.value.current_revision_id;emit('command','Registrar corrección auditable',`/expenses/${selected.value.id}/corrections`,body);}else{body.trip_id=tripId.value||null;emit('command','Registrar gasto','/expenses',body);}}
function decide():void{if(!selected.value)return;emit('command',decision.value==='approved'?'Aprobar gasto':'Rechazar gasto',`/expenses/${selected.value.id}/decisions`,{expected_revision_id:selected.value.current_revision_id,decision:decision.value,reason:decisionReason.value});}
function attachment(event:Event):void{file.value=event.target instanceof HTMLInputElement?event.target.files?.[0]??null:null;}
function attach():void{if(selected.value&&file.value)emit('command','Adjuntar comprobante privado',`/expenses/${selected.value.id}/receipts`,{},file.value);}
watch(()=>props.epoch,()=>{reset();file.value=null;void load(page.value);});void load();void lookup();onBeforeUnmount(()=>{alive=false;generation++;});
const errorId=useId();
</script>
<template><section class="space-y-5"><form class="panel grid gap-3 sm:grid-cols-2 lg:grid-cols-4" @submit.prevent="load()"><h2 class="font-semibold lg:col-span-4 sm:col-span-2">Consultar gastos</h2><label>Buscar concepto o categoría<input v-model="search" class="field" :disabled="locked||loading"></label><label>Estado<select aria-label="Estado" v-model="status" class="field" :disabled="locked||loading"><option value="">Todos</option><option value="pending">Pendientes</option><option value="approved">Aprobados</option><option value="rejected">Rechazados</option></select></label><label>Moneda del filtro<select aria-label="Moneda del filtro" v-model="currencyFilter" class="field" :disabled="locked||loading"><option value="">Todas · sin sumar monedas</option><option>CRC</option><option>USD</option></select></label><label>Viaje del filtro<input v-model="tripFilter" class="field" :disabled="locked||loading" placeholder="Identificador del viaje"></label><label>Desde<input v-model="from" type="date" class="field" :disabled="locked||loading"></label><label>Hasta<input v-model="to" type="date" class="field" :disabled="locked||loading"></label><button class="btn-secondary" :disabled="locked||loading">Consultar gastos</button></form><p v-if="loading" role="status">Consultando gastos…</p><div class="panel overflow-x-auto"><table class="data-table"><thead><tr><th>Concepto / categoría</th><th>Importe</th><th>Fecha</th><th>Estado</th><th>Detalle</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.concept}}<br>{{row.category}}</td><td>{{money(row.amount,row.currency)}}</td><td>{{date(row.occurred_at)}}</td><td>{{labels[row.status]}}</td><td><button class="btn-secondary" :disabled="locked||loading" @click="inspect(row)">Ver gasto</button></td></tr></tbody></table><p v-if="!loading&&!rows.length">No hay gastos para estos filtros.</p></div><div class="flex gap-3 items-center"><button class="btn-secondary" :disabled="locked||loading||page<=1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{last}}</span><button class="btn-secondary" :disabled="locked||loading||page>=last" @click="load(page+1)">Siguiente</button></div>
<form class="panel grid gap-3 sm:grid-cols-2" @submit.prevent="submit"><h2 class="font-semibold sm:col-span-2">{{editing?'Corregir gasto con historial':'Registrar gasto'}}</h2><label>Concepto<input v-model="concept" class="field" maxlength="255" required :disabled="locked||loading" :aria-invalid="!!errors['concept']?.length" :aria-describedby="errors['concept']?.length ? `${errorId}-concept-error` : undefined"></label><FieldError :id="`${errorId}-concept-error`" :errors="errors['concept']"/><label>Categoría<input v-model="category" class="field" maxlength="255" required :disabled="locked||loading" placeholder="Descripción administrativa" :aria-invalid="!!errors['category']?.length" :aria-describedby="errors['category']?.length ? `${errorId}-category-error` : undefined"></label><FieldError :id="`${errorId}-category-error`" :errors="errors['category']"/><label>Importe del gasto<input v-model="amount" class="field" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?" required :disabled="locked||loading" :aria-invalid="!!errors['amount']?.length" :aria-describedby="errors['amount']?.length ? `${errorId}-amount-error` : undefined"></label><FieldError :id="`${errorId}-amount-error`" :errors="errors['amount']"/><label>Moneda del gasto<select aria-label="Moneda del gasto" v-model="currency" class="field" :disabled="locked||loading" :aria-invalid="!!errors['currency']?.length" :aria-describedby="errors['currency']?.length ? `${errorId}-currency-error` : undefined"><option>CRC</option><option>USD</option></select></label><FieldError :id="`${errorId}-currency-error`" :errors="errors['currency']"/><label>Fecha y hora del gasto · Costa Rica<input v-model="occurredAt" class="field" type="datetime-local" required :disabled="locked||loading" :aria-invalid="!!errors['occurred_at']?.length" :aria-describedby="errors['occurred_at']?.length ? `${errorId}-occurredAt-error` : undefined"></label><FieldError :id="`${errorId}-occurredAt-error`" :errors="errors['occurred_at']"/><label>Viaje asociado · opcional<input v-model="tripId" list="expense-trips" class="field" :disabled="locked||loading||editing" placeholder="Vacío para gasto general" :aria-invalid="!!errors['trip_id']?.length" :aria-describedby="errors['trip_id']?.length ? `${errorId}-tripId-error` : undefined"><datalist id="expense-trips"><option v-for="trip in trips" :key="trip.id" :value="trip.id">{{trip.execution_status}}</option></datalist></label><FieldError :id="`${errorId}-tripId-error`" :errors="errors['trip_id']"/><label class="sm:col-span-2">Descripción<textarea v-model="description" class="field" maxlength="4000" :disabled="locked||loading" :aria-invalid="!!errors['description']?.length" :aria-describedby="errors['description']?.length ? `${errorId}-description-error` : undefined"/></label><FieldError :id="`${errorId}-description-error`" :errors="errors['description']"/><label v-if="editing" class="sm:col-span-2">Motivo de corrección<textarea v-model="reason" class="field" required :disabled="locked||loading"/></label><div class="flex flex-wrap gap-3"><button class="btn-primary" :disabled="locked||loading">{{editing?'Registrar corrección':'Registrar gasto'}}</button><button v-if="editing" type="button" class="btn-secondary" :disabled="locked||loading" @click="reset">Volver a nuevo gasto</button></div><p class="text-sm sm:col-span-2">El gasto entra pendiente de aprobación. Puedes adjuntar comprobantes privados desde su detalle una vez registrado.</p></form>
<section v-if="selected" class="panel space-y-4 [overflow-wrap:anywhere]"><div class="flex flex-wrap justify-between gap-3"><h2 class="font-semibold">Detalle del gasto</h2><button class="btn-secondary" :disabled="locked||loading" @click="selected=null">Cerrar detalle</button></div><p>{{selected.concept}} · {{selected.category}}</p><p>{{money(selected.amount,selected.currency)}} · {{labels[selected.status]}}</p><p>{{date(selected.occurred_at)}} · responsable {{selected.created_by_id}}</p><p>{{selected.description}}</p><p>{{selected.trip_id?`Viaje: ${selected.trip_id}`:'Gasto general de empresa'}}</p><button class="btn-secondary" :disabled="locked||loading" @click="correct">Corregir con historial</button><form v-if="admin&&selected.status==='pending'" class="grid gap-3 sm:grid-cols-2" @submit.prevent="decide"><h3 class="sm:col-span-2 font-semibold">Decisión administrativa</h3><label>Decisión<select aria-label="Decisión" v-model="decision" class="field" :disabled="locked||loading"><option value="approved">Aprobar</option><option value="rejected">Rechazar</option></select></label><label>Motivo de decisión<textarea v-model="decisionReason" class="field" required :disabled="locked||loading"/></label><button class="btn-primary" :disabled="locked||loading">Registrar decisión</button></form><form class="space-y-3" @submit.prevent="attach"><h3 class="font-semibold">Comprobantes privados</h3><label>Comprobante PDF, JPG o PNG<input type="file" class="field" accept="application/pdf,image/jpeg,image/png" :disabled="locked||loading" required @change="attachment"></label><button class="btn-secondary" :disabled="locked||loading||!file">Adjuntar comprobante</button></form><ul><li v-for="receipt in selected.receipts" :key="receipt.id"><a class="text-blue-700 underline" :href="`/api/expenses/receipts/${receipt.id}/download`">Descargar comprobante autorizado · {{receipt.mime_type}}</a> · {{date(receipt.registered_at)}}</li></ul><h3 class="font-semibold">Historial de versiones y decisiones</h3><ol class="space-y-3"><li v-for="(version,index) in selected.versions" :key="index" class="border border-blue-200 p-3 rounded"><p class="font-medium">{{version.concept}} · {{version.category}}</p><p>{{version.currency}} {{version.amount}} · {{version.occurred_at}}</p><p>{{version.description}}</p><p>Motivo: {{version.reason??'Registro original'}} · responsable {{version.recorded_by_id??version.created_by_id}}</p></li></ol><ol class="space-y-3"><li v-for="(item,index) in selected.decisions" :key="index" class="border border-blue-200 p-3 rounded"><p>{{item.decision==='approved'?'Aprobado':'Rechazado'}} · {{item.reason}}</p><p>Responsable {{item.decided_by_id}} · {{item.decided_at}}</p></li></ol></section></section></template>
